    "<svg viewBox=\"0 0 220 150\" width=\"220\" role=\"img\" aria-label=\"Eş kümesi Benzer kümesinin içinde; 1 Eş kümesinde; 2, 3 ve 4 Benzer kümesinde Eş dışında\"><rect x=\"2\" y=\"2\" width=\"216\" height=\"146\" rx=\"8\" fill=\"#ffffff\" stroke=\"#475569\" stroke-width=\"1.5\"/><ellipse cx=\"100\" cy=\"80\" rx=\"80\" ry=\"58\" fill=\"#dbeafe\" stroke=\"#1d4ed8\" stroke-width=\"2\"/><ellipse cx=\"72\" cy=\"90\" rx=\"34\" ry=\"30\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"2\"/><g font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\"><text x=\"112\" y=\"44\" fill=\"#1d4ed8\">Benzer</text><text x=\"72\" y=\"78\" fill=\"#b45309\">Eş</text></g><g font-size=\"16\" font-weight=\"bold\" fill=\"#1e293b\" text-anchor=\"middle\"><text x=\"126\" y=\"128\">3</text><text x=\"72\" y=\"106\">1</text><text x=\"140\" y=\"74\">2</text><text x=\"152\" y=\"102\">4</text></g></svg><br>Şema II",
    "<svg viewBox=\"0 0 220 150\" width=\"220\" role=\"img\" aria-label=\"Eş ve Benzer kümeleri ayrık; 1 yalnız Eş kümesinde; 2 ve 4 Benzer kümesinde; 3 iki kümenin de dışında\"><rect x=\"2\" y=\"2\" width=\"216\" height=\"146\" rx=\"8\" fill=\"#ffffff\" stroke=\"#475569\" stroke-width=\"1.5\"/><circle cx=\"52\" cy=\"82\" r=\"40\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"2\"/><circle cx=\"152\" cy=\"78\" r=\"50\" fill=\"#dbeafe\" stroke=\"#1d4ed8\" stroke-width=\"2\"/><g font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\"><text x=\"52\" y=\"66\" fill=\"#b45309\">Eş</text><text x=\"152\" y=\"54\" fill=\"#1d4ed8\">Benzer</text></g><g font-size=\"16\" font-weight=\"bold\" fill=\"#1e293b\" text-anchor=\"middle\"><text x=\"52\" y=\"100\">1</text><text x=\"138\" y=\"94\">2</text><text x=\"168\" y=\"108\">4</text><text x=\"205\" y=\"140\">3</text></g></svg><br>Şema III",
    "<svg viewBox=\"0 0 220 150\" width=\"220\" role=\"img\" aria-label=\"Eş kümesi Benzer kümesinin içinde; 1 Eş kümesinde; 2 Benzer kümesinde Eş dışında; 3 ve 4 iki kümenin de dışında\"><rect x=\"2\" y=\"2\" width=\"216\" height=\"146\" rx=\"8\" fill=\"#ffffff\" stroke=\"#475569\" stroke-width=\"1.5\"/><ellipse cx=\"100\" cy=\"80\" rx=\"80\" ry=\"58\" fill=\"#dbeafe\" stroke=\"#1d4ed8\" stroke-width=\"2\"/><ellipse cx=\"72\" cy=\"90\" rx=\"34\" ry=\"30\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"2\"/><g font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\"><text x=\"112\" y=\"44\" fill=\"#1d4ed8\">Benzer</text><text x=\"72\" y=\"78\" fill=\"#b45309\">Eş</text></g><g font-size=\"16\" font-weight=\"bold\" fill=\"#1e293b\" text-anchor=\"middle\"><text x=\"72\" y=\"106\">1</text><text x=\"140\" y=\"92\">2</text><text x=\"186\" y=\"140\">3</text><text x=\"204\" y=\"140\">4</text></g></svg><br>Şema IV"
